// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ANCHToken} from "../src/ANCHToken.sol";

contract InvMutTest is Test {
    ANCHToken c;

    function setUp() public { c = new ANCHToken(address(new __InvMutHandleStub()), address(this)); }

    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(this)); // must differ from current owner so the bug is observable

        vm.prank(address(this));
        c.changeOwner(newOwner);

        assertTrue(c.owner() == newOwner);
    }
}

